local classes = {}

classes.BadRequest = errors.define({
  tag = "BadRequest",
  categories = { "BadRequestError" },
  matchers = { { status = 400 } },
  fields = { "details" },
})
classes.Conflict = errors.define({
  tag = "Conflict",
  categories = { "ConflictError" },
  matchers = { { status = 409 } },
  fields = { "details" },
})
classes.Forbidden = errors.define({
  tag = "Forbidden",
  categories = { "AuthError" },
  matchers = { { status = 403 } },
  fields = { "details" },
})
classes.NotFound = errors.define({
  tag = "NotFound",
  categories = { "BadRequestError" },
  matchers = { { status = 404 } },
  fields = { "details" },
})
classes.VaultScopeInsufficient = errors.define({
  tag = "VaultScopeInsufficient",
  categories = { "AuthError" },
  matchers = { { status = 403, message = { includes = "insufficient authentication scopes" } } },
  fields = { "details" },
})

